def matches(s1, s2):
    return s1[-1] == s2[0]

def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    parts = input_data.split()
    if len(parts) != 3:
        return
    A, B, C = parts
    if matches(A, B) and matches(B, C):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()

